function Kill-Owned($records){foreach($r in @($records)){if($null-ne$r.wrapper-and-not$r.wrapper.HasExited){&taskkill.exe /PID $r.wrapper.Id /T /F 2>&1|Out-Null}}}
function Wait-Evidence([string]$path,$r,[DateTime]$deadline,[string]$label){while(-not(Test-Path $path)){if($r.wrapper.HasExited){$r.wrapper.Refresh();throw "${label}: lane $($r.lane) wrapper exited $($r.wrapper.ExitCode)."};if((Get-Date)-ge$deadline){throw "$label timeout: lane $($r.lane)."};Start-Sleep -Milliseconds 100;$r.wrapper.Refresh()}}
