isolated-editor-lanes-serial-license-admission-v1';waveId=$waveId;barrierToken=$token;laneCount=3;releasedAtUtc=[DateTime]::UtcNow.ToString('o');formalCampaign=$false}) 15;$deadline=(Get-Date).AddSeconds($WaveTimeoutSeconds);do{$alive=@($records|Where-Object{-not$_.wrapper.HasExited});if(-not$alive.Count){break};if((Get-Date)-ge$deadline){throw "Wave $wave timeout."};Start-Sleep -Milliseconds 500;foreach($r in $alive){$r.wrapper.Refresh()}}while($true)}finally{$env:PSModulePath=$old}
